package com.alpharip.staffmod.AuditFindingsBoard;public final class AuditFindingsValidator {private AuditFindingsValidator(){}public static void validate(String t,String d,AuditFindingCategory c,AuditFindingSeverity s){if(t==null||t.trim().isEmpty())throw new IllegalArgumentException("Finding title is required");if(t.trim().length()>100)throw new IllegalArgumentException("Title must be 100 characters or fewer");if(d==null||d.trim().isEmpty())throw new IllegalArgumentException("Description is required");if(d.trim().length()>2000)throw new IllegalArgumentException("Description must be 2000 characters or fewer");if(c==null||s==null)throw new IllegalArgumentException("Category and severity are required");} }
